-- FFH hosted apply: migration 20261120100000_ffh_p11_set_aside_integrity
-- GENERATED by scripts/hosted/build-apply.mjs from the files at the commit the Builder names. Do not edit.
-- Paste the WHOLE file into a new Supabase SQL Editor query and Run ONCE. One transaction: if any check fails you get
-- one error starting FFH_APPLY_FAIL that names every failed check, and NOTHING is applied. Success ends with a table
-- of PASS rows; paste that table back to the Builder.
begin;

create temp table ffh_apply_results(step int, check_name text, ok boolean, detail text);

-- 1. Pre-check: hosted is exactly at the previous migration and has not recorded this one.
do $pre$
declare n int;
begin
  select count(*) into n from supabase_migrations.schema_migrations;
  if n <> 27 then
    raise exception 'FFH_APPLY_FAIL nothing was applied: pre-check expected 27 recorded migrations, found %', n;
  end if;
  if exists (select 1 from supabase_migrations.schema_migrations where version = '20261120100000') then
    raise exception 'FFH_APPLY_FAIL nothing was applied: migration 20261120100000 is already recorded';
  end if;
  insert into ffh_apply_results values (1, 'pre-check: 27 migrations, 20261120100000 not yet recorded', true, null);
end
$pre$;

-- 2. The migration.
-- FFH-P11 independent audit remediation (audit PASS at 694df32 with P11-01..03 MEDIUM; Ryan: "fix all of them now",
-- 2026-11-20). Hardens public.bill_set_asides at the database boundary so DIRECT authenticated API writes uphold the
-- same invariants as the app's forms. No data is changed; the released P10 app never reads this table.
--
-- P11-01  reserved_amount was numeric(14,2): sub-cent input was silently rounded and 'NaN' passed ">= 0". It becomes an
--         unconstrained numeric (binary-compatible, no table rewrite) with a CHECK that refuses NaN, negatives, values
--         above 999,999,999,999.99 and anything that is not a whole number of cents.
-- P11-02  Clients could write any column (id, audit columns, version, timestamps). Insert/update privileges are now
--         limited to the columns a person actually supplies; the trigger also refuses an id change. Referential
--         ON DELETE SET NULL (account deletion) runs as the table owner and still works through the existing
--         audit-only pass-through, which clients can no longer reach.
-- P11-03  A reserve-only edit skipped the bill check, so it could save against a cycle whose bill had just changed
--         schedule or become ineligible, or whose due date had just passed. Every insert and every non-pass-through
--         update now locks the bill row (FOR SHARE) and revalidates the cycle in the same transaction.


alter table public.bill_set_asides
  alter column reserved_amount type numeric,
  drop constraint bill_set_asides_reserved_amount_check,
  add constraint bill_set_asides_reserved_amount_check check (
    reserved_amount <> 'NaN'::numeric
    and reserved_amount >= 0
    and reserved_amount <= 999999999999.99
    and reserved_amount = round(reserved_amount, 2)
  );

revoke insert, update on public.bill_set_asides from authenticated;
grant insert (household_id, expense_id, cycle_due_date, cycle_anchor_date, cycle_recurrence, reserved_amount)
  on public.bill_set_asides to authenticated;
grant update (cycle_due_date, cycle_anchor_date, cycle_recurrence, reserved_amount)
  on public.bill_set_asides to authenticated;

create or replace function private.bill_set_aside_before_write()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_recurrence text;
  v_anchor date;
  v_payment numeric;
  v_step integer;
  v_months integer;
  v_day integer;
  v_last_day integer;
begin
  if tg_op = 'INSERT' then
    new.version := 1;
    new.created_by := auth.uid();
    new.created_at := now();
  else
    -- ON DELETE SET NULL from a deleted account (created_by/updated_by -> auth.users): only an audit column becomes
    -- NULL and nothing else changes. Let it through as is; re-stamping it would point at the deleted account, fail the
    -- foreign key and so block that person's account deletion. Clients cannot reach this path: they have no UPDATE
    -- privilege on the audit columns (P11-02); referential actions run as the table owner.
    if (new.created_by is null or new.updated_by is null)
       and (new.created_by is distinct from old.created_by or new.updated_by is distinct from old.updated_by)
       and (new.created_by is null or new.created_by = old.created_by)
       and (new.updated_by is null or new.updated_by = old.updated_by)
       and (new.id, new.household_id, new.expense_id, new.cycle_due_date, new.cycle_anchor_date, new.cycle_recurrence,
            new.reserved_amount, new.version, new.created_at, new.updated_at)
           is not distinct from (old.id, old.household_id, old.expense_id, old.cycle_due_date, old.cycle_anchor_date,
            old.cycle_recurrence, old.reserved_amount, old.version, old.created_at, old.updated_at) then
      return new;
    end if;
    if new.id is distinct from old.id or new.household_id is distinct from old.household_id
       or new.expense_id is distinct from old.expense_id then
      raise exception 'a set-aside cannot be moved to another bill' using errcode = '22023';
    end if;
    new.version := old.version + 1;
    new.created_by := old.created_by;
    new.created_at := old.created_at;
  end if;
  new.updated_by := auth.uid();
  new.updated_at := now();

  -- P11-03: every write (a new tracker, a confirmed cycle AND a reserve-only edit) is checked against the bill as it is
  -- now, with the bill row held until commit so a concurrent schedule change or delete cannot slip in between.
  select e.recurrence, e.due_anchor_date, e.payment_amount into v_recurrence, v_anchor, v_payment
    from public.expenses e
    where e.id = new.expense_id and e.household_id = new.household_id
    for share;
  if not found then
    raise exception 'bill not found' using errcode = '42501';
  end if;
  if v_recurrence not in ('quarterly', 'yearly') or v_anchor is null or v_payment is null or v_payment <= 0 then
    raise exception 'only a scheduled quarterly or yearly bill with an amount can be tracked' using errcode = '22023';
  end if;
  if new.cycle_recurrence is distinct from v_recurrence or new.cycle_anchor_date is distinct from v_anchor then
    raise exception 'the bill schedule changed; confirm the cycle again' using errcode = '22023';
  end if;
  if new.cycle_due_date < (now() at time zone 'utc')::date then
    raise exception 'this set-aside cycle has passed; confirm the next cycle first' using errcode = '22023';
  end if;
  -- Occurrence k of the anchor: k * step months later, the anchor's day clamped to that month's length.
  v_step := case v_recurrence when 'quarterly' then 3 else 12 end;
  v_months := (extract(year from new.cycle_due_date)::integer * 12 + extract(month from new.cycle_due_date)::integer)
            - (extract(year from v_anchor)::integer * 12 + extract(month from v_anchor)::integer);
  v_day := extract(day from v_anchor)::integer;
  v_last_day := extract(day from (date_trunc('month', new.cycle_due_date) + interval '1 month - 1 day'))::integer;
  if v_months < 0 or v_months % v_step <> 0
     or extract(day from new.cycle_due_date)::integer <> least(v_day, v_last_day) then
    raise exception 'the cycle date is not a due date of this bill' using errcode = '22023';
  end if;
  return new;
end;
$$;

revoke all on function private.bill_set_aside_before_write() from public, anon, authenticated;

-- 3. Record it.
insert into supabase_migrations.schema_migrations(version, name) values ('20261120100000', 'ffh_p11_set_aside_integrity');
insert into ffh_apply_results values (2, 'migration 20261120100000 applied and recorded', true, null);

-- 4. Paste repair (scripts/rls-local/strip-cr.sql): functions whose body picked up CR characters.
do $strip$
declare
  f record;
  fixed int := 0;
begin
  for f in
    select p.oid, n.nspname, p.proname
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
    where n.nspname in ('public', 'private')
      and p.prokind = 'f'
      and position(E'\r' in p.prosrc) > 0
      and not exists (select 1 from pg_depend d where d.objid = p.oid and d.deptype = 'e')
  loop
    execute replace(pg_get_functiondef(f.oid), E'\r', '');
    fixed := fixed + 1;
    raise notice 'CR_STRIPPED %.%', f.nspname, f.proname;
  end loop;
  raise notice 'CR_STRIP_DONE functions_fixed=%', fixed;
end
$strip$;
insert into ffh_apply_results
select 3, 'paste repair: no function body contains CR', count(*) = 0, count(*)::text || ' left'
from pg_proc p join pg_namespace n on n.oid = p.pronamespace
where n.nspname in ('public', 'private') and position(E'\r' in p.prosrc) > 0;

-- 5. Phase checks (scripts/hosted/checks/20261120100000.sql).
insert into ffh_apply_results select 4, 'phase check: ' || c.check_name, c.ok, null from (
select 'every saved set-aside amount is a valid whole-cent amount' as check_name,
       not exists (select 1 from public.bill_set_asides
         where reserved_amount = 'NaN'::numeric or reserved_amount < 0 or reserved_amount > 999999999999.99
            or reserved_amount <> round(reserved_amount, 2)) as ok
union all
select 'clients cannot write set-aside ids, versions or audit columns',
       not (has_column_privilege('authenticated', 'public.bill_set_asides', 'id', 'UPDATE')
         or has_column_privilege('authenticated', 'public.bill_set_asides', 'version', 'UPDATE')
         or has_column_privilege('authenticated', 'public.bill_set_asides', 'created_by', 'UPDATE')
         or has_column_privilege('authenticated', 'public.bill_set_asides', 'id', 'INSERT')
         or has_column_privilege('authenticated', 'public.bill_set_asides', 'version', 'INSERT')
         or has_column_privilege('authenticated', 'public.bill_set_asides', 'created_by', 'INSERT'))
union all
select 'clients can still write the set-aside input columns',
       has_column_privilege('authenticated', 'public.bill_set_asides', 'reserved_amount', 'UPDATE')
       and has_column_privilege('authenticated', 'public.bill_set_asides', 'cycle_due_date', 'UPDATE')
       and has_column_privilege('authenticated', 'public.bill_set_asides', 'expense_id', 'INSERT')
union all
select 'signed-out visitors still have no access to set-asides',
       not (has_table_privilege('anon', 'public.bill_set_asides', 'SELECT')
         or has_column_privilege('anon', 'public.bill_set_asides', 'reserved_amount', 'UPDATE'))
union all
select 'set-aside trigger function not callable by API roles',
       not (has_function_privilege('anon', 'private.bill_set_aside_before_write()', 'EXECUTE')
         or has_function_privilege('authenticated', 'private.bill_set_aside_before_write()', 'EXECUTE'))
) c;

-- 6. Parity against scripts/rls-local/parity.expected.txt at this commit.
create temp table ffh_apply_parity as
WITH
pub_tables AS (
  SELECT c.oid, c.relname, c.relrowsecurity, c.relforcerowsecurity
  FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public' AND c.relkind IN ('r', 'p')
),
our_functions AS (
  SELECT p.oid, n.nspname, p.proname
  FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
  WHERE n.nspname IN ('public', 'private')
    AND NOT EXISTS (SELECT 1 FROM pg_depend d
                    WHERE d.objid = p.oid AND d.deptype = 'e')
),
sections(section, item) AS (
  SELECT 'migrations', m.version
  FROM pg_catalog.pg_namespace mn
  CROSS JOIN LATERAL (
    SELECT (xpath('/row/v/text()', x))[1]::text AS version
    FROM unnest(xpath('/table/row',
      query_to_xml('SELECT version AS v FROM supabase_migrations.schema_migrations',
                   false, false, ''))) AS x
  ) m
  WHERE mn.nspname = 'supabase_migrations'
    AND to_regclass('supabase_migrations.schema_migrations') IS NOT NULL
  UNION ALL
  SELECT 'rls', relname || ':' || relrowsecurity || ':' || relforcerowsecurity
  FROM pub_tables
  UNION ALL
  SELECT 'policies', concat_ws('|', tablename, policyname, permissive,
         (SELECT string_agg(r, ',' ORDER BY r) FROM unnest(roles) r),
         cmd, coalesce(qual, '-'), coalesce(with_check, '-'))
  FROM pg_policies WHERE schemaname = 'public'
  UNION ALL
  SELECT DISTINCT 'table_grants', concat_ws('|', t.relname,
         CASE WHEN a.grantee = 0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,
         a.privilege_type, a.is_grantable)
  FROM pub_tables t
  JOIN pg_class c ON c.oid = t.oid
  CROSS JOIN LATERAL aclexplode(coalesce(c.relacl, acldefault('r', c.relowner))) a
  WHERE a.grantee = 0 OR pg_get_userbyid(a.grantee) IN ('anon', 'authenticated')
  UNION ALL
  SELECT 'columns', concat_ws('|', c.table_name, c.column_name, c.data_type,
         c.is_nullable, coalesce(c.column_default, '-'))
  FROM information_schema.columns c
  JOIN pub_tables t ON t.relname = c.table_name
  WHERE c.table_schema = 'public'
  UNION ALL
  SELECT 'constraints', concat_ws('|', t.relname, k.conname, k.contype,
         pg_get_constraintdef(k.oid))
  FROM pg_constraint k JOIN pub_tables t ON t.oid = k.conrelid
  UNION ALL
  SELECT 'triggers', concat_ws('|', t.relname, g.tgname, g.tgfoid::regprocedure::text,
         g.tgenabled, g.tgtype)
  FROM pg_trigger g JOIN pub_tables t ON t.oid = g.tgrelid
  WHERE NOT g.tgisinternal
  UNION ALL
  SELECT 'functions', concat_ws('|', f.nspname, f.proname,
         pg_get_function_identity_arguments(p.oid), p.prosecdef, p.provolatile,
         coalesce(array_to_string(p.proconfig, ','), '-'), md5(p.prosrc))
  FROM our_functions f JOIN pg_proc p ON p.oid = f.oid
  UNION ALL
  SELECT 'function_grants', concat_ws('|', f.nspname, f.proname,
         pg_get_function_identity_arguments(f.oid), r.rolname,
         has_function_privilege(r.oid, f.oid, 'EXECUTE'))
  FROM our_functions f
  CROSS JOIN pg_roles r WHERE r.rolname IN ('anon', 'authenticated')
)
SELECT section, count(*) AS items, md5(string_agg(item, E'\n' ORDER BY item)) AS fingerprint
FROM sections
GROUP BY section
ORDER BY section;
insert into ffh_apply_results
select 5, 'parity: ' || e.section, p.items = e.items and p.fingerprint = e.fp,
       case when p.section is null then 'missing' when p.items = e.items and p.fingerprint = e.fp then null
            else p.items::text || '|' || p.fingerprint end
from (values
  ('columns', 275, '7309705e7e48be8309c829fcdf491e3f'),
  ('constraints', 217, '5efd5db72a43963c3f6c6d75fb375682'),
  ('function_grants', 56, 'fd7a5539898a5f21be983958f865a4a3'),
  ('functions', 28, '2a84490356f6b8f57e13e4a74acd86ab'),
  ('migrations', 28, '70519c86f5e9d5c13f756b2d38fd5324'),
  ('policies', 78, '021bbf3fe8922bc7542b07abe672ca02'),
  ('rls', 21, '74b4f28612fb824c6cfb3a53521b1110'),
  ('table_grants', 237, '2de4fd0d9807680f5ce90e01362e95fa'),
  ('triggers', 6, 'def81bc2f77625e43e3fce38c62841e6')
) e(section, items, fp)
left join ffh_apply_parity p on p.section = e.section;
insert into ffh_apply_results
select 5, 'parity: unexpected section ' || p.section, false, p.items::text || '|' || p.fingerprint
from ffh_apply_parity p
where p.section not in ('columns', 'constraints', 'function_grants', 'functions', 'migrations', 'policies', 'rls', 'table_grants', 'triggers');

-- 7. All or nothing.
do $fin$
declare bad text;
begin
  select string_agg(check_name || coalesce(' [' || detail || ']', ''), '; ' order by step, check_name) into bad
  from ffh_apply_results where not ok;
  if bad is not null then
    raise exception 'FFH_APPLY_FAIL nothing was applied: %', bad;
  end if;
end
$fin$;

commit;

select step, check_name, case when ok then 'PASS' else 'FAIL' end as result
from ffh_apply_results order by step, check_name;
